import{c as e,Q as o,j as r,m as s}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"异构系统与编程模型","description":"","frontmatter":{},"headers":[{"level":1,"title":"异构系统与编程模型","slug":"异构系统与编程模型"},{"level":2,"title":"什么是异构系统？","slug":"什么是异构系统"},{"level":2,"title":"昇腾应用程序的组成","slug":"昇腾应用程序的组成"},{"level":2,"title":"Host 与 Device 的协作流程","slug":"host-与-device-的协作流程"},{"level":2,"title":"AI Core：NPU 的核心计算单元","slug":"ai-corenpu-的核心计算单元"},{"level":2,"title":"SIMD 与 SIMT 并行模型","slug":"simd-与-simt-并行模型"},{"level":3,"title":"SIMD 核函数编程基本步骤（遵循 SPMD 模型）","slug":"simd-核函数编程基本步骤遵循-spmd-模型"},{"level":3,"title":"SIMT 核函数编程基本步骤（遵循 SPMD 模型）","slug":"simt-核函数编程基本步骤遵循-spmd-模型"},{"level":2,"title":"编程模型选型指南","slug":"编程模型选型指南"},{"level":2,"title":"小结","slug":"小结"}],"relativePath":"guide/入门教程/快速入门/异构系统与编程模型.md","filePath":"guide/入门教程/快速入门/异构系统与编程模型.md"}'),l={name:"guide/入门教程/快速入门/异构系统与编程模型.md"};function n(i,t,d,a,g,h){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="异构系统与编程模型" tabindex="-1">异构系统与编程模型 <a class="header-anchor" href="#异构系统与编程模型" aria-label="Permalink to &quot;异构系统与编程模型&quot;">​</a></h1><blockquote><p>本文作为算子编程快速入门章节，将从昇腾异构系统基础入手，逐步拆解编程模型核心要素，帮助您快速建立昇腾算子编程的整体认知，为后续实操开发奠定基础。</p></blockquote><hr><h2 id="什么是异构系统" tabindex="-1">什么是异构系统？ <a class="header-anchor" href="#什么是异构系统" aria-label="Permalink to &quot;什么是异构系统？&quot;">​</a></h2><p>基于昇腾处理器的异构系统，核心是<strong>通过两类功能互补的处理器协同工作</strong>，兼顾通用计算与高密度并行计算，实现整体性能最优。</p><table tabindex="0"><thead><tr><th>角色</th><th>组成</th><th>职责</th></tr></thead><tbody><tr><td><strong>Host（主机）</strong></td><td>CPU + Host Memory</td><td>通用计算、资源管理、任务调度、统筹协调</td></tr><tr><td><strong>Device（设备）</strong></td><td>昇腾 NPU + Device Memory</td><td>高密度并行计算（深度学习推理/训练、图像处理等）</td></tr></tbody></table><blockquote><p>💡 <strong>通俗理解</strong>：Host 如同项目经理，负责规划、分配、协调；Device 如同专业工程师团队，专注于高效完成高强度、重复性的计算工作。两者分工协作，提升整体效率。</p></blockquote><hr><h2 id="昇腾应用程序的组成" tabindex="-1">昇腾应用程序的组成 <a class="header-anchor" href="#昇腾应用程序的组成" aria-label="Permalink to &quot;昇腾应用程序的组成&quot;">​</a></h2><p>基于昇腾异构系统的应用程序必然包含两部分代码，分工明确、协同运行：</p><table tabindex="0"><thead><tr><th>代码类型</th><th>运行位置</th><th>编程语言</th><th>核心职责</th></tr></thead><tbody><tr><td><strong>Host 代码</strong></td><td>CPU（Host 侧）</td><td>标准 C/C++</td><td>管理 Device 设备、搬运数据、启动 NPU 任务、同步状态</td></tr><tr><td><strong>Device 代码</strong></td><td>NPU（Device 侧）</td><td><strong>Ascend C</strong></td><td>执行具体的并行计算任务，一般称为<a href="./../../编程指南/编程模型/AI-Core-SIMD编程/核函数.html">核函数</a></td></tr></tbody></table><blockquote><p>✅ <strong>便捷提示</strong>：Host 代码与 Device 代码可编写在同一个 <code>.asc</code> 文件中，由毕昇编译器自动识别、分别编译，简化开发流程。</p></blockquote><hr><h2 id="host-与-device-的协作流程" tabindex="-1">Host 与 Device 的协作流程 <a class="header-anchor" href="#host-与-device-的协作流程" aria-label="Permalink to &quot;Host 与 Device 的协作流程&quot;">​</a></h2><p>Host 侧通过调用 <strong>CANN Runtime API</strong> 完成与 Device 的协同工作。典型流程如下：</p><ol><li><strong>分配内存</strong>：在 Device Memory 中申请输入/输出所需的空间。</li><li><strong>搬运数据</strong>：将输入数据从 Host Memory 拷贝到 Device Memory（数据需进入 Device 侧才能被 NPU 访问）。</li><li><strong>启动 NPU 计算任务</strong>：调用 Device 侧预先编写的<a href="./../../编程指南/编程模型/AI-Core-SIMD编程/核函数.html">核函数</a>，NPU 开始并行计算。</li><li><strong>同步等待</strong>：Host 端等待 NPU 执行完成，确保数据计算完整（避免未完成就读取结果）。</li><li><strong>回传结果</strong>：将计算结果从 Device Memory 拷贝回 Host Memory，供后续处理。</li></ol><blockquote><p>📌 <strong>关键点</strong>：Host 与 NPU 是异步执行的，第 4 步的同步必不可少，否则可能读取到未完成的数据。</p></blockquote><hr><h2 id="ai-core-npu-的核心计算单元" tabindex="-1">AI Core：NPU 的核心计算单元 <a class="header-anchor" href="#ai-core-npu-的核心计算单元" aria-label="Permalink to &quot;AI Core：NPU 的核心计算单元&quot;">​</a></h2><p>NPU 是 Device 侧的计算核心，而 <strong>AI Core</strong> 则是 NPU 内部的“最小计算单元”。一枚 NPU 芯片通常集成多个 AI Core，可并行处理不同的数据块，大幅提升整体计算吞吐量。</p><p>每个 AI Core 内部结构高度优化，专门适配并行计算需求，核心组件包括：</p><ul><li><strong>标量处理单元</strong>：处理控制流（如分支、循环）和地址计算，类似传统 CPU 核心，是 AI Core 的“控制核心”。</li><li><strong>向量处理单元</strong>：执行向量运算，是 SIMD / SIMT 两种并行模型的主要载体。不同昇腾芯片架构对两种模式的支持有所差异。</li><li><strong>矩阵运算单元</strong>：专门优化矩阵乘加运算，仅兼容 SIMD 模式，是深度学习卷积、全连接层等算子的“性能加速核心”。</li><li><strong>本地存储</strong>：用于缓存计算所需的数据，有效降低对全局 Device Memory 的访问延迟，提升计算效率。</li></ul><blockquote><p>🧬 <strong>架构演进</strong>：Ascend 950PR/Ascend 950DT 架构之前，AI Core <strong>仅支持 SIMD</strong>；从 Ascend 950PR/Ascend 950DT 架构开始，向量处理单元<strong>同时支持 SIMD 和 SIMT</strong>，为不同算子任务提供更灵活的选择。</p></blockquote><hr><h2 id="simd-与-simt-并行模型" tabindex="-1">SIMD 与 SIMT 并行模型 <a class="header-anchor" href="#simd-与-simt-并行模型" aria-label="Permalink to &quot;SIMD 与 SIMT 并行模型&quot;">​</a></h2><p><strong>SIMD</strong>（Single Instruction Multiple Data）与 <strong>SIMT</strong>（Single Instruction Multiple Threads）是昇腾 AI Core 支持的两种核心并行执行模型，也是算子编程的关键。两者在核心逻辑、适用场景上差异显著，对比如下：</p><table tabindex="0"><thead><tr><th>模型</th><th>全称</th><th>核心思想</th><th>通俗比喻</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>SIMD</strong></td><td>单指令多数据</td><td>一条指令同时操作多个同构数据</td><td>一个厨师同时翻炒多份相同的菜</td><td>规整、高密度计算（矩阵乘、卷积、逐元素运算）</td></tr><tr><td><strong>SIMT</strong></td><td>单指令多线程</td><td>一条指令驱动多个独立线程</td><td>一个厨师指挥多个助手，各切各的菜</td><td>不规则访问、分支密集、稀疏计算（如稀疏卷积）</td></tr></tbody></table><h3 id="simd-核函数编程基本步骤-遵循-spmd-模型" tabindex="-1">SIMD 核函数编程基本步骤（遵循 SPMD 模型） <a class="header-anchor" href="#simd-核函数编程基本步骤-遵循-spmd-模型" aria-label="Permalink to &quot;SIMD 核函数编程基本步骤（遵循 SPMD 模型）&quot;">​</a></h3><blockquote><p><strong>SPMD（Single Program, Multiple Data）</strong>：每个 AI Core 运行同一份程序，但处理不同的数据块。</p></blockquote><ol><li><strong>Tiling（分块）</strong>：将数据划分为均匀的块，每个 AI Core 负责一块，实现负载均衡。</li><li><strong>数据搬入</strong>：调用专用 API 将数据从 Device Memory 搬到本地存储。</li><li><strong>数据计算</strong>：调用向量指令批量处理。注意数据搬运与计算异步，需插入同步指令。</li><li><strong>结果搬出</strong>：调用专用 API 将本地存储中的结果搬回 Device Memory。</li></ol><h3 id="simt-核函数编程基本步骤-遵循-spmd-模型" tabindex="-1">SIMT 核函数编程基本步骤（遵循 SPMD 模型） <a class="header-anchor" href="#simt-核函数编程基本步骤-遵循-spmd-模型" aria-label="Permalink to &quot;SIMT 核函数编程基本步骤（遵循 SPMD 模型）&quot;">​</a></h3><blockquote><p><strong>SPMD（Single Program, Multiple Data）</strong>：每个线程运行同一份程序，但每个线程处理不同的数据元素。</p></blockquote><ol><li><strong>Tiling（分块）</strong>：建立线程索引与数据索引的一一对应关系。</li><li><strong>数据搬入</strong>：通过指针直接访问 Device Memory，硬件自动加载到寄存器，无需专用 API。</li><li><strong>数据计算</strong>：编写标量代码（支持分支、循环）；多线程协作时需插入同步指令。</li><li><strong>结果搬出</strong>：通过指针直接写回 Device Memory，无需专用 API。</li></ol><blockquote><p>📌 <strong>提示</strong>：Host 端可通过 <code>&lt;&lt;&lt;&gt;&gt;&gt;</code> 语法糖或 CANN Runtime API 调用并运行核函数。</p></blockquote><hr><h2 id="编程模型选型指南" tabindex="-1">编程模型选型指南 <a class="header-anchor" href="#编程模型选型指南" aria-label="Permalink to &quot;编程模型选型指南&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编程模型</th><th>支持范围</th><th>适用场景</th><th>芯片支持</th></tr></thead><tbody><tr><td><strong>SIMD</strong></td><td>向量、矩阵、融合计算</td><td>规整、高密度任务（卷积、矩阵乘、逐元素变换）</td><td>昇腾全系列</td></tr><tr><td><strong>SIMT</strong></td><td>仅向量计算</td><td>离散访问、复杂分支、稀疏计算</td><td>Ascend 950PR/Ascend 950DT</td></tr><tr><td><strong>SIMD+SIMT 混合</strong></td><td>同 SIMT 范围（结合两者优势）</td><td>用 SIMT 处理不规则逻辑，用 SIMD 批量高效计算</td><td>Ascend 950PR/Ascend 950DT</td></tr></tbody></table><blockquote><p>📌 <strong>快速选型建议</strong>：</p><ul><li>开发常规高性能算子（如矩阵乘、逐元素算子）时，建议使用 SIMD 编程模型。该模型支持昇腾全系列产品，且具有较高的能效比。</li><li>对于涉及离散数据或复杂分支逻辑的算子，建议使用 SIMT 编程模型。</li></ul></blockquote><hr><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>昇腾异构计算的核心逻辑可概括为： <strong>Host（CPU）调度 + Device（NPU）执行</strong></p><ul><li><strong>Host</strong> 侧：统筹资源、调度任务。</li><li><strong>Device</strong> 侧：核心是 <strong>AI Core</strong>，支持 <strong>SIMD</strong>（主力模型，全系列兼容）和 <strong>SIMT</strong>（补充模型，适配复杂场景）两种并行模式。</li></ul><p><strong>算子编程的关键</strong>：根据数据的<strong>规整度、访存模式、分支密度</strong>，选择合适的编程模型，充分发挥 AI Core 的硬件性能，即可高效开发出高性能的 Ascend C 算子。</p><blockquote><p>🚀 后续章节将围绕具体编程实操，深入讲解两种模型的算子开发细节。</p></blockquote>',44)])])}const b=e(l,[["render",n]]);export{u as __pageData,b as default};
